LEVEL = 1
CFG = {1: 10, 2: 30, 3: 100}
N = CFG[LEVEL]
log = [("set", "k%d" % (i % 5), i) for i in range(N)]
rebuilt = {}
for _, k, v in log: rebuilt[k] = v
live = dict(rebuilt)
if N > 20: live["k0"] = -999  # tampered live state
diverged = {k for k in rebuilt if rebuilt[k] != live.get(k)}
print("replayed:", N, "| divergences:", sorted(diverged) or ["none"])

